});

describe('CostEstimator', () => {
  let engine: SlippageEngine;
  let estimator: CostEstimator;

  beforeEach(() => {
    engine = new SlippageEngine();
    estimator = new CostEstimator(engine);
  });

  it('should estimate total cost', async () => {
    const order: OrderRequest = {
      symbol: 'BTC/USDT',
      side: 'buy',
      size: new Decimal(1),
      type: 'market',
      timeInForce: 'GTC'
    };

    const estimate = await estimator.estimateTotalCost(order);
    assert(estimate !== undefined);
    assert(estimate.total instanceof Decimal);
    assert(estimate.breakdown !== undefined);
    assert(estimate.confidence > 0);
  });

  it('should check trade execution', async () => {
    const order: OrderRequest = {
      symbol: 'BTC/USDT',
      side: 'buy',
      size: new Decimal(1),
      type: 'market',
      timeInForce: 'GTC'
    };

    const maxCost = new Decimal(1000);
    const shouldExecute = await estimator.shouldExecuteTrade(order, maxCost);
    assert(typeof shouldExecute === 'boolean');
  });
});

describe('ImpactSimulator', () => {
  let engine: SlippageEngine;
  let simulator: ImpactSimulator;

  beforeEach(() => {
    engine = new SlippageEngine();
    simulator = new ImpactSimulator(engine);
  });

  it('should simulate execution scenarios', async () => {
    const order: OrderRequest = {
      symbol: 'BTC/USDT',
      side: 'buy',
      size: new Decimal(1),
      type: 'market',
      timeInForce: 'GTC'
    };

    const scenarios = ['best_case', 'expected', 'worst_case'];
    const simulations = await simulator.simulateExecution(order, scenarios as any);

    assert(simulations.length === 3);
    simulations.forEach(sim => {
      assert(sim.scenario !== undefined);
      assert(typeof sim.expectedSlippage === 'number');
      assert(typeof sim.worstCaseSlippage === 'number');
      assert(typeof sim.executionTime === 'number');
    });
  });
});

import { Decimal } from 'decimal.js';
import { nj } from 'numjs';
import {
  SlippageEngine as ISlippageEngine,
  OrderRequest,
  MarketState,
  SlippageEstimate,
  TimeHorizon,
  TradingRegime,
  AlmgrenChrissParams
} from './types.js';
import { logger } from '../logging/logger.js';

export class SlippageEngine implements ISlippageEngine {
  private baselineVolatility = 0.02; // 2% daily volatility baseline
  private maxVolatilityMultiplier = 5.0;
  private minimumSlippage = new Decimal('0.0001'); // 0.01% minimum slippage
  private emaAlpha = 0.1; // Smoothing factor for volatility EMA
  private emaState = new Map<string, number>();

  constructor() {
    logger.info('SlippageEngine initialized', { service: 'SlippageEngine' });
  }

  async estimateSlippage(
    order: OrderRequest,
    horizon: TimeHorizon = 'immediate'
  ): Promise<SlippageEstimate> {
    // This will be integrated with real market data later
    // For now, return a placeholder estimate
    const baseSlippage = new Decimal('0.001'); // 0.1% base slippage

    return {
      totalSlippage: baseSlippage,
      confidence: 0.5,
      breakdown: {
        permanentImpact: baseSlippage.mul(0.6),
        temporaryImpact: baseSlippage.mul(0.3),
        spreadCost: baseSlippage.mul(0.1)
      },
      horizon
    };
  }

  private calculatePermanentImpact(
    order: OrderRequest,
    marketState: MarketState,
    regime: TradingRegime
  ): Decimal {
    const params = this.getRegimeParameters(regime);
    const volatility = marketState.volatility;
    const adv = this.estimateADV(order.symbol); // Placeholder
    const size = order.size;

    // Almgren-Chriss permanent impact: γ * σ * √(Q/ADV)
    const impact = params.gamma * volatility * Math.sqrt(Number(size) / adv);

    return new Decimal(impact);
  }

  private calculateTemporaryImpact(
    order: OrderRequest,
    marketState: MarketState,
    regime: TradingRegime
  ): Decimal {
    const params = this.getRegimeParameters(regime);
    const volatility = marketState.volatility;
    const volume = this.estimateCurrentVolume(order.symbol); // Placeholder
    const size = order.size;
    const horizon: TimeHorizon = 'immediate';

    // Temporary impact: λ * σ * (Q/V) * e^(-κt)
    const lambda = params.lambda;
    const kappa = params.kappa;
    const timeToExecution = this.getTimeToExecution(horizon);

    const impact = lambda * volatility * (Number(size) / volume) * Math.exp(-kappa * timeToExecution);

    return new Decimal(Math.max(impact, 0));
  }

  private calculateSpreadCost(order: OrderRequest, marketState: MarketState): Decimal {
    const spread = marketState.spread;
    const direction = order.side === 'buy' ? 1 : -1;

    // Spread cost: 0.5 * spread * direction
    return spread.mul(0.5).mul(direction);
  }

  private calculateVolatilityMultiplier(marketState: MarketState): number {
    const vol = marketState.volatility;
    const symbol = 'default'; // Would use actual symbol

    const emaKey = `volatility_${symbol}`;
    const prevEma = this.emaState.get(emaKey) || vol;
    const currentEma = this.emaAlpha * vol + (1 - this.emaAlpha) * prevEma;

    this.emaState.set(emaKey, currentEma);

    return Math.min(currentEma / this.baselineVolatility, this.maxVolatilityMultiplier);
  }

  private calculateSizeMultiplier(order: OrderRequest, marketState: MarketState): number {
    const relativeSize = Number(order.size) / Number(marketState.depth.bidVolume.plus(marketState.depth.askVolume));

    if (relativeSize < 0.01) return 1.0;
    if (relativeSize < 0.1) return 1 + (relativeSize - 0.01) * 2;
    return Math.pow(relativeSize, 0.7);
  }

  private calculateToxicityAdjustment(marketState: MarketState): number {
    const vpin = marketState.depth.vpin;
    const imbalance = Math.abs(0); // Placeholder for order imbalance

    const toxicityScore = (vpin + imbalance) / 2;
    return 1 + toxicityScore * 0.5; // toxicitySensitivity = 0.5
  }

  private calculateConfidence(marketState: MarketState, regime: TradingRegime): number {
    const agePenalty = Math.min((Date.now() - marketState.timestamp) / 1000 / 100, 1);
    const volatilityPenalty = Math.min(marketState.volatility / 0.1, 1); // maxVolatility = 0.1
    const depthPenalty = Math.min(1 / Number(marketState.depth.bidVolume.plus(marketState.depth.askVolume)), 1);

    return Math.max(0, 1 - agePenalty - volatilityPenalty - depthPenalty);
  }

  private getRegimeParameters(regime: TradingRegime): AlmgrenChrissParams {
    const params: Record<TradingRegime, AlmgrenChrissParams> = {
      high_liquidity: { gamma: 0.1, lambda: 0.2, kappa: 0.8, alpha: 0.4, rho: 0.1 },
      normal: { gamma: 0.3, lambda: 0.3, kappa: 0.5, alpha: 0.6, rho: 0.2 },
      low_liquidity: { gamma: 0.6, lambda: 0.5, kappa: 0.2, alpha: 0.8, rho: 0.3 },
      volatile: { gamma: 0.8, lambda: 0.7, kappa: 0.1, alpha: 1.0, rho: 0.4 },
      uncertain: { gamma: 0.4, lambda: 0.4, kappa: 0.4, alpha: 0.7, rho: 0.25 }
    };

    return params[regime];
  }

  private estimateADV(symbol: string): number {
    // Placeholder - would query historical data
    return 1000000; // $1M daily volume
  }

  private estimateCurrentVolume(symbol: string): number {
    // Placeholder - would query real-time data
    return 10000; // $10k per minute
  }

  private getTimeToExecution(horizon: TimeHorizon): number {
    const horizons = {
      immediate: 0.1, // 100ms
      seconds: 1.0,   // 1 second
      minutes: 60.0   // 1 minute
    };

    return horizons[horizon];
  }
}

import { randomUUID } from 'crypto';
import os from 'os';
import path from 'path';
import { LogRotator, TimeBasedRotator } from './rotation.js';

export type LogLevel = 'info' | 'warn' | 'error' | 'debug';

export interface LogContext {
  requestId?: string;
  route?: string;
  method?: string;
  service?: string;
  [key: string]: unknown;
}

const parseLevel = (value: string | undefined): LogLevel => {
  // Default to 'info' in production, 'debug' in development
  const defaultLevel = process.env.NODE_ENV === 'production' ? 'info' : 'debug';
  const normalized = (value || defaultLevel).toLowerCase();
  if (normalized === 'debug' || normalized === 'info' || normalized === 'warn' || normalized === 'error') {
    return normalized;
  }
  return 'info';
};

const minimumLevel = parseLevel(process.env.LOG_LEVEL);
const levelOrder: Record<LogLevel, number> = {
  debug: 10,
  info: 20,
  warn: 30,
  error: 40
};

const shouldLog = (level: LogLevel): boolean => levelOrder[level] >= levelOrder[minimumLevel];

// Log rotation setup
const logDir = process.env.LOG_DIR || path.join(process.cwd(), 'logs');
const logFile = path.join(logDir, 'trading-system.log');

// Ensure log directory exists
try {
  if (!require('fs').existsSync(logDir)) {
    require('fs').mkdirSync(logDir, { recursive: true });
  }
} catch (e) {
  // If we can't create log directory, fall back to stdout/stderr only
}

const sizeRotator = new LogRotator(logFile, {
  maxSizeBytes: 10 * 1024 * 1024, // 10MB
  maxFiles: 5,
  compress: false
});

const timeRotator = new TimeBasedRotator(logFile, {
  maxFiles: 7, // Keep 7 days of logs
  compress: false
});

// Start periodic checks
sizeRotator.startPeriodicCheck(60000); // Check every minute
timeRotator.checkAndRotate(); // Check on startup

function writeLogLine(line: string) {
  // Write to stdout/stderr
  if (line.includes('"level":"error"')) {
    process.stderr.write(`${line}\n`);
  } else {
    process.stdout.write(`${line}\n`);
  }

  // Write to file with rotation
  try {
    if (require('fs').existsSync(logDir)) {
      // Check for time-based rotation
      timeRotator.checkAndRotate();

      // Check for size-based rotation
      if (sizeRotator.needsRotation()) {
        sizeRotator.rotate();
      }

      require('fs').appendFileSync(logFile, `${line}\n`);
    }
  } catch (e) {
    // If file write fails, continue with stdout/stderr only
  }
}

function write(level: LogLevel, message: string, context: LogContext = {}) {
  if (!shouldLog(level)) return;

  const payload = {
    ts: new Date().toISOString(),
    level,
    message,
    service: context.service || 'trading-system',
    pid: process.pid,
    hostname: os.hostname(),
    ...context
  };

  const line = JSON.stringify(payload);
  writeLogLine(line);
}

export const logger = {
  debug: (message: string, context?: LogContext) => write('debug', message, context),
  info: (message: string, context?: LogContext) => write('info', message, context),
  warn: (message: string, context?: LogContext) => write('warn', message, context),
  error: (message: string, context?: LogContext) => write('error', message, context)
};

export function getRequestId(headerValue?: string | string[]): string {
  if (Array.isArray(headerValue)) {
    return headerValue[0] || randomUUID();
  }

  return typeof headerValue === 'string' && headerValue.trim().length > 0
    ? headerValue.trim()
    : randomUUID();
}

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export interface RotationConfig {
  maxSizeBytes: number;      // e.g., 10 * 1024 * 1024 for 10MB
  maxFiles: number;          // e.g., 5 to keep last 5 files
  compress: boolean;         // whether to gzip old logs
}

const DEFAULT_CONFIG: RotationConfig = {
  maxSizeBytes: 10 * 1024 * 1024, // 10MB
  maxFiles: 5,
  compress: false
};

export class LogRotator {
  private logFilePath: string;
  private config: RotationConfig;
  private checkInterval: NodeJS.Timeout | null = null;

  constructor(logFilePath: string, config: Partial<RotationConfig> = {}) {
    this.logFilePath = logFilePath;
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Check if log file needs rotation based on size
   */
  needsRotation(): boolean {
    try {
      if (!fs.existsSync(this.logFilePath)) {
        return false;
      }
      const stats = fs.statSync(this.logFilePath);
      return stats.size >= this.config.maxSizeBytes;
    } catch (error) {
      console.error('Error checking log file size:', error);
      return false;
    }
  }

  /**
   * Rotate the log file
   */
  rotate(): boolean {
    try {
      if (!fs.existsSync(this.logFilePath)) {
        return false;
      }

      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      const rotatedPath = `${this.logFilePath}.${timestamp}`;

      // Rename current log file
      fs.renameSync(this.logFilePath, rotatedPath);

      // Compress if enabled
      if (this.config.compress) {
        this.compressFile(rotatedPath);
      }

      // Clean up old files
      this.cleanupOldFiles();

      return true;
    } catch (error) {
      console.error('Error rotating log file:', error);
      return false;
    }
  }

  /**
   * Compress a log file using gzip
   */
  private compressFile(filePath: string): void {
    import('zlib').then(({ gzipSync }) => {
      try {
        const data = fs.readFileSync(filePath);
        const compressed = gzipSync(data);
        fs.writeFileSync(`${filePath}.gz`, compressed);
        fs.unlinkSync(filePath);
      } catch (error) {
        console.error('Error compressing log file:', error);
      }
    }).catch(() => {});
  }

  /**
   * Remove old rotated files beyond maxFiles limit
   */
  private cleanupOldFiles(): void {
    try {
      const logDir = path.dirname(this.logFilePath);
      const logBasename = path.basename(this.logFilePath);
      const files = fs.readdirSync(logDir)
        .filter(f => f.startsWith(logBasename) && f !== logBasename)
        .map(f => ({
          name: f,
          path: path.join(logDir, f),
          time: fs.statSync(path.join(logDir, f)).mtimeMs
        }))
        .sort((a, b) => b.time - a.time);

      // Remove files beyond maxFiles limit
      for (let i = this.config.maxFiles - 1; i < files.length; i++) {
        try {
          fs.unlinkSync(files[i].path);
        } catch (error) {
          console.error(`Error removing old log file ${files[i].path}:`, error);
        }
      }
    } catch (error) {
      console.error('Error cleaning up old log files:', error);
    }
  }

  /**
   * Start periodic rotation check
   */
  startPeriodicCheck(intervalMs: number = 60000): void {
    if (this.checkInterval) {
      return;
    }
    this.checkInterval = setInterval(() => {
      if (this.needsRotation()) {
        this.rotate();
      }
    }, intervalMs);
    this.checkInterval.unref?.();
  }

  /**
   * Stop periodic rotation check
   */
  stopPeriodicCheck(): void {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
      this.checkInterval = null;
    }
  }
}

/**
 * Daily time-based rotation utility
 */
export class TimeBasedRotator {
  private logFilePath: string;
  private lastRotationDate: string;
  private config: RotationConfig;

  constructor(logFilePath: string, config: Partial<RotationConfig> = {}) {
    this.logFilePath = logFilePath;
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.lastRotationDate = new Date().toISOString().split('T')[0];
  }

  /**
   * Check if a new day has started and rotate if needed
   */
  checkAndRotate(): boolean {
    const today = new Date().toISOString().split('T')[0];
    if (today !== this.lastRotationDate) {
      this.lastRotationDate = today;
      return this.rotate();
    }
    return false;
  }

  /**
   * Rotate the log file (time-based)
   */
  rotate(): boolean {
    try {
      if (!fs.existsSync(this.logFilePath)) {
        return false;
      }

      const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
      const rotatedPath = `${this.logFilePath}.${yesterday}`;

      // Remove existing rotated file for this date
      if (fs.existsSync(rotatedPath)) {
        fs.unlinkSync(rotatedPath);
      }

      // Rename current log file
      fs.renameSync(this.logFilePath, rotatedPath);

      // Compress if enabled
      if (this.config.compress) {
        this.compressFile(rotatedPath);
      }

      // Clean up old files
      this.cleanupOldFiles();

      return true;
    } catch (error) {
      console.error('Error rotating log file:', error);
      return false;
    }
  }

  private compressFile(filePath: string): void {
    import('zlib').then(({ gzipSync }) => {
      try {
        const data = fs.readFileSync(filePath);
        const compressed = gzipSync(data);
        fs.writeFileSync(`${filePath}.gz`, compressed);
        fs.unlinkSync(filePath);
      } catch (error) {
        console.error('Error compressing log file:', error);
      }
    }).catch(() => {});
  }

  private cleanupOldFiles(): void {
    try {
      const logDir = path.dirname(this.logFilePath);
      const logBasename = path.basename(this.logFilePath);
      const files = fs.readdirSync(logDir)
        .filter(f => f.startsWith(logBasename) && f !== logBasename)
        .map(f => ({
          name: f,
          path: path.join(logDir, f),
          time: fs.statSync(path.join(logDir, f)).mtimeMs
        }))
        .sort((a, b) => b.time - a.time);

      for (let i = this.config.maxFiles - 1; i < files.length; i++) {
        try {
          fs.unlinkSync(files[i].path);
        } catch (error) {
          console.error(`Error removing old log file ${files[i].path}:`, error);
        }
      }
    } catch (error) {
      console.error('Error cleaning up old log files:', error);
    }
  }
}

import { Decimal } from 'decimal.js';
import {
  LiquidityAnalyzer as ILiquidityAnalyzer,
  OrderBookSnapshot,
  LiquidityProfile,
  SlippageProfile,
  LiquidityTier,
  OrderRequest
} from './types.js';
import { logger } from '../logging/logger.js';

export class LiquidityAnalyzer implements ILiquidityAnalyzer {
  private orderBookCache = new Map<string, OrderBookSnapshot>();
  private cacheTimeout = 100; // 100ms cache timeout
  private exchangeConnector: any; // Would be injected

  constructor(exchangeConnector?: any) {
    this.exchangeConnector = exchangeConnector;
    logger.info('LiquidityAnalyzer initialized', { service: 'LiquidityAnalyzer' });
  }

  async analyzeLiquidity(symbol: string, timestamp: number): Promise<any> {
    // Simplified implementation - would analyze real order book data
    return {
      effectiveDepth: new Decimal(75),
      resiliencyScore: 4.5,
      slippageProfile: [{
        size: new Decimal(1),
        expectedSlippage: new Decimal(0.003),
        confidence: 0.85
      }],
      tier: 'medium' as const
    };
  }

  async analyzeDepth(
    symbol: string,
    orderSize: Decimal,
    side: 'buy' | 'sell'
  ): Promise<LiquidityProfile> {
    const book = await this.getLatestBook(symbol);
    if (!book) {
      logger.warn('No order book data available', { service: 'LiquidityAnalyzer', symbol });
      return this.getDefaultProfile(orderSize);
    }

    const effectiveDepth = this.calculateEffectiveDepth(book, orderSize, side);
    const resiliency = this.measureResiliency(book, orderSize);
    const slippageProfile = this.generateSlippageProfile(book, orderSize);
    const tier = this.classifyLiquidityTier(effectiveDepth, resiliency);

    return {
      effectiveDepth,
      resiliencyScore: resiliency,
      slippageProfile,
      tier
    };
  }

  private async getLatestBook(symbol: string): Promise<OrderBookSnapshot | null> {
    const cached = this.orderBookCache.get(symbol);
    if (cached && (Date.now() - cached.timestamp) < this.cacheTimeout) {
      return cached;
    }

    if (this.exchangeConnector) {
      try {
        const orderBookData = await this.exchangeConnector.getOrderBook(symbol);
        const snapshot = this.convertToSnapshot(orderBookData);
        this.orderBookCache.set(symbol, snapshot);
        return snapshot;
      } catch (error) {
        logger.warn('Failed to fetch order book from exchange', {
          service: 'LiquidityAnalyzer',
          symbol,
          error: error.message
        });
      }
    }

    // Fallback to mock data
    return this.getMockOrderBook(symbol);
  }

  private calculateEffectiveDepth(
    book: OrderBookSnapshot,
    orderSize: Decimal,
    side: 'buy' | 'sell'
  ): Decimal {
    const levels = side === 'buy' ? book.asks : book.bids;
    let cumulativeSize = new Decimal(0);
    let cumulativeVolume = new Decimal(0);

    for (const [price, size] of levels) {
      const remainingSize = orderSize.minus(cumulativeVolume);
      if (remainingSize.lte(0)) break;

      const fillSize = Decimal.min(remainingSize, size);
      cumulativeVolume = cumulativeVolume.plus(fillSize);
      cumulativeSize = cumulativeSize.plus(fillSize.mul(price));
    }

    return cumulativeVolume.div(orderSize).mul(100); // Percentage of order that can be filled
  }

  private measureResiliency(book: OrderBookSnapshot, orderSize: Decimal): number {
    // Resiliency = time to fill order at current depth
    const avgSpread = Number(book.spread);
    const totalDepth = Number(book.totalBidDepth.plus(book.totalAskDepth));
    const relativeSize = Number(orderSize) / totalDepth;

    // Simple resiliency metric: inverse of relative size (higher = more resilient)
    const resiliency = Math.min(1 / relativeSize, 10);

    // Factor in spread stability (placeholder)
    const spreadFactor = Math.max(0, 1 - avgSpread / 0.01); // Penalize wide spreads

    return resiliency * spreadFactor;
  }

  private generateSlippageProfile(
    book: OrderBookSnapshot,
    orderSize: Decimal
  ): SlippageProfile[] {
    const sizes = [0.1, 0.25, 0.5, 1.0, 2.0]; // Percentage of order size
    const profile: SlippageProfile[] = [];

    for (const sizePct of sizes) {
      const testSize = orderSize.mul(sizePct);
      const slippage = this.calculateSlippageForSize(book, testSize);

      profile.push({
        size: testSize,
        expectedSlippage: slippage,
        confidence: 0.8 // Placeholder
      });
    }

    return profile;
  }

  private calculateSlippageForSize(book: OrderBookSnapshot, size: Decimal): Decimal {
    // Simplified slippage calculation based on order book shape
    const midPrice = book.midPrice;
    let cumulativeVolume = new Decimal(0);
    let weightedPrice = new Decimal(0);

    // Use bid side for buy orders, ask side for sell orders
    const levels = book.asks; // Simplified - would depend on side

    for (const [price, levelSize] of levels) {
      const remainingSize = size.minus(cumulativeVolume);
      if (remainingSize.lte(0)) break;

      const fillSize = Decimal.min(remainingSize, levelSize);
      weightedPrice = weightedPrice.plus(fillSize.mul(price));
      cumulativeVolume = cumulativeVolume.plus(fillSize);
    }

    if (cumulativeVolume.gt(0)) {
      const avgExecutionPrice = weightedPrice.div(cumulativeVolume);
      return avgExecutionPrice.minus(midPrice).abs().div(midPrice);
    }

    return new Decimal(0.01); // Default 1% slippage if no depth
  }

  private classifyLiquidityTier(effectiveDepth: Decimal, resiliency: number): LiquidityTier {
    const depthScore = Number(effectiveDepth);

    if (depthScore > 80 && resiliency > 5) return 'high';
    if (depthScore > 50 && resiliency > 2) return 'medium';
    return 'low';
  }

  private getDefaultProfile(orderSize: Decimal): LiquidityProfile {
    return {
      effectiveDepth: new Decimal(50),
      resiliencyScore: 2,
      slippageProfile: [{
        size: orderSize,
        expectedSlippage: new Decimal(0.005),
        confidence: 0.3
      }],
      tier: 'low'
    };
  }

  private getMockOrderBook(symbol: string): OrderBookSnapshot {
    // Mock order book for development
    const midPrice = new Decimal(50000);
    const spread = new Decimal(1);

    const bids: Array<[Decimal, Decimal, number]> = [];
    const asks: Array<[Decimal, Decimal, number]> = [];

    // Generate 10 levels
    for (let i = 0; i < 10; i++) {
      const bidPrice = midPrice.minus(spread.mul(i + 1));
      const askPrice = midPrice.plus(spread.mul(i + 1));
      const size = new Decimal(1 + Math.random() * 5);

      bids.push([bidPrice, size, 1]);
      asks.push([askPrice, size, 1]);
    }

    return {
      symbol,
      timestamp: Date.now(),
      bids,
      asks,
      spread,
      midPrice,
      totalBidDepth: new Decimal(50),
      totalAskDepth: new Decimal(50),
      updateId: Date.now(),
      exchange: 'mock'
    };
  }

  private convertToSnapshot(orderBookData: any): OrderBookSnapshot {
    const bids: Array<[Decimal, Decimal, number]> = orderBookData.bids.map(
      ([price, size]: [number, number]) => [new Decimal(price), new Decimal(size), 1]
    );

    const asks: Array<[Decimal, Decimal, number]> = orderBookData.asks.map(
      ([price, size]: [number, number]) => [new Decimal(price), new Decimal(size), 1]
    );

    const bestBid = bids[0]?.[0] || new Decimal(0);
    const bestAsk = asks[0]?.[0] || new Decimal(0);
    const spread = bestAsk.minus(bestBid);
    const midPrice = bestBid.plus(bestAsk).div(2);

    const totalBidDepth = bids.reduce((sum, [, size]) => sum.plus(size), new Decimal(0));
    const totalAskDepth = asks.reduce((sum, [, size]) => sum.plus(size), new Decimal(0));

    return {
      symbol: orderBookData.symbol,
      timestamp: orderBookData.timestamp,
      bids,
      asks,
      spread,
      midPrice,
      totalBidDepth,
      totalAskDepth,
      updateId: Date.now(), // Simplified
      exchange: orderBookData.exchange
    };
  }

  // Method to update order book cache (called by ExchangeConnector)
  updateOrderBook(snapshot: OrderBookSnapshot): void {
    this.orderBookCache.set(snapshot.symbol, snapshot);
  }
}

import { Decimal } from 'decimal.js';
import {
  CostEstimator as ICostEstimator,
  OrderRequest,
  TotalCostEstimate,
  FeeBreakdown,
  NetworkCostEstimate
} from './types.js';
import { SlippageEngine } from './engine.js';
import { logger } from '../logging/logger.js';

export class CostEstimator implements ICostEstimator {
  private slippageEngine: SlippageEngine;
  private feeCache = new Map<string, { fees: FeeBreakdown; timestamp: number }>();
  private cacheTimeout = 3600000; // 1 hour

  constructor(slippageEngine: SlippageEngine) {
    this.slippageEngine = slippageEngine;
    logger.info('CostEstimator initialized', { service: 'CostEstimator' });
  }

  async estimateTotalCost(order: OrderRequest): Promise<TotalCostEstimate> {
    const [slippage, fees, networkCosts] = await Promise.all([
      this.slippageEngine.estimateSlippage(order),
      this.getFees(order),
      this.estimateNetworkCosts(order)
    ]);

    const total = slippage.totalSlippage.plus(fees.total).plus(networkCosts.total);

    return {
      total,
      breakdown: { slippage, fees, networkCosts },
      confidence: Math.min(slippage.confidence, fees.confidence, networkCosts.confidence)
    };
  }

  private async getFees(order: OrderRequest): Promise<FeeBreakdown> {
    const cacheKey = `${order.symbol}_${order.type}`;
    const cached = this.feeCache.get(cacheKey);

    if (cached && (Date.now() - cached.timestamp) < this.cacheTimeout) {
      return cached.fees;
    }

    // TODO: Integrate with ccxt for real exchange fees
    const fees = this.getMockFees(order);
    this.feeCache.set(cacheKey, { fees, timestamp: Date.now() });

    return fees;
  }

  private getMockFees(order: OrderRequest): FeeBreakdown {
    // Mock fee structure - would be replaced with real exchange data
    const isMaker = order.type === 'limit' && order.limitPrice !== undefined;

    let makerFee: Decimal;
    let takerFee: Decimal;

    if (order.symbol.includes('BTC')) {
      makerFee = new Decimal('0.001'); // 0.1%
      takerFee = new Decimal('0.002'); // 0.2%
    } else {
      makerFee = new Decimal('0.002'); // 0.2%
      takerFee = new Decimal('0.004'); // 0.4%
    }

    const fee = isMaker ? makerFee : takerFee;
    const total = fee.mul(order.size);

    return {
      makerFee,
      takerFee,
      total,
      confidence: 0.9
    };
  }

  private async estimateNetworkCosts(order: OrderRequest): Promise<NetworkCostEstimate> {
    // For crypto trading, network costs are minimal
    // This would be more relevant for on-chain operations

    const gasCost = new Decimal(0);
    const priorityFee = new Decimal(0);
    const total = gasCost.plus(priorityFee);

    return {
      gasCost,
      priorityFee,
      total,
      confidence: 1.0
    };
  }

  // Pre-trade cost check for trading engine
  async shouldExecuteTrade(order: OrderRequest, maxCostThreshold: Decimal): Promise<boolean> {
    try {
      const costEstimate = await this.estimateTotalCost(order);

      logger.info('Cost estimate for order', {
        service: 'CostEstimator',
        symbol: order.symbol,
        side: order.side,
        size: order.size.toString(),
        estimatedTotalCost: costEstimate.total.toString(),
        confidence: costEstimate.confidence,
        threshold: maxCostThreshold.toString()
      });

      return costEstimate.total.lte(maxCostThreshold) && costEstimate.confidence > 0.5;
    } catch (error) {
      logger.error('Failed to estimate cost for trade check', {
        service: 'CostEstimator',
        error: error.message,
        symbol: order.symbol
      });

      // Fail closed - reject trade if cost estimation fails
      return false;
    }
  }

  // Method to update fee cache (called by background job)
  updateFees(symbol: string, exchange: string, makerFee: number, takerFee: number): void {
    const feeBreakdown: FeeBreakdown = {
      makerFee: new Decimal(makerFee),
      takerFee: new Decimal(takerFee),
      total: new Decimal(0), // Will be calculated per order
      confidence: 0.95
    };

    this.feeCache.set(`${symbol}_limit`, { fees: feeBreakdown, timestamp: Date.now() });
    this.feeCache.set(`${symbol}_market`, { fees: feeBreakdown, timestamp: Date.now() });

    logger.info('Updated fee cache', {
      service: 'CostEstimator',
      symbol,
      exchange,
      makerFee,
      takerFee
    });
  }
}

import { Decimal } from 'decimal.js';
import {
  ImpactSimulator as IImpactSimulator,
  OrderRequest,
  ExecutionSimulation,
  ExecutionScenario,
  OrderBookSnapshot,
  MarketState
} from './types.js';
import { SlippageEngine } from './engine.js';
import { logger } from '../logging/logger.js';

export class ImpactSimulator implements IImpactSimulator {
  private slippageEngine: SlippageEngine;
  private pathsPerSimulation = 1000;

  constructor(slippageEngine: SlippageEngine) {
    this.slippageEngine = slippageEngine;
    logger.info('ImpactSimulator initialized', { service: 'ImpactSimulator' });
  }

  async simulateImpact(order: OrderRequest, marketState: MarketState): Promise<any> {
    // Simplified implementation - would use full slippage modeling
    const permanentImpact = new Decimal(0.001); // 0.1% permanent impact
    const temporaryImpact = new Decimal(0.002); // 0.2% temporary impact
    const spreadCost = new Decimal(0.0005); // 0.05% spread cost

    return {
      totalSlippage: permanentImpact.plus(temporaryImpact).plus(spreadCost),
      confidence: 0.8,
      breakdown: {
        permanentImpact,
        temporaryImpact,
        spreadCost
      }
    };
  }

  async simulateExecution(
    order: OrderRequest,
    scenarios: ExecutionScenario[] = ['best_case', 'worst_case', 'expected']
  ): Promise<ExecutionSimulation[]> {
    const simulations = scenarios.map(scenario =>
      this.runMonteCarloSimulation(order, scenario)
    );

    return await Promise.all(simulations);
  }

  private async runMonteCarloSimulation(
    order: OrderRequest,
    scenario: ExecutionScenario
  ): Promise<ExecutionSimulation> {
    const paths = this.generatePricePaths(order.symbol, scenario, this.pathsPerSimulation);
    const executions = paths.map(path =>
      this.simulateOrderExecution(order, path)
    );

    const slippageValues = executions.map(e => Number(e.slippage));
    const timeValues = executions.map(e => e.timeToFill);

    return {
      scenario,
      expectedSlippage: this.mean(slippageValues),
      worstCaseSlippage: this.percentile(slippageValues, 95),
      executionTime: this.mean(timeValues)
    };
  }

  private generatePricePaths(
    symbol: string,
    scenario: ExecutionScenario,
    numPaths: number
  ): PricePath[] {
    // Simplified price path generation
    const paths: PricePath[] = [];
    const basePrice = 50000; // Mock current price
    const timeSteps = 100; // 100 time steps for execution
    const dt = 1 / timeSteps;

    for (let i = 0; i < numPaths; i++) {
      const path: PricePath = {
        prices: [],
        timestamps: []
      };

      let price = basePrice;
      const startTime = Date.now();

      for (let t = 0; t < timeSteps; t++) {
        const drift = this.getScenarioDrift(scenario);
        const volatility = this.getScenarioVolatility(scenario);
        const randomShock = this.randomNormal() * volatility * Math.sqrt(dt);

        price *= Math.exp((drift - volatility * volatility / 2) * dt + randomShock);

        path.prices.push(price);
        path.timestamps.push(startTime + t * 10); // 10ms per step
      }

      paths.push(path);
    }

    return paths;
  }

  private simulateOrderExecution(order: OrderRequest, path: PricePath): ExecutionResult {
    let remainingSize = Number(order.size);
    let totalCost = 0;
    let filledSize = 0;
    let executionTime = 0;

    // Simplified market order execution
    for (let i = 0; i < path.prices.length && remainingSize > 0; i++) {
      const price = path.prices[i];
      const time = path.timestamps[i];

      // Execute a portion of the order at current price
      const fillSize = Math.min(remainingSize * 0.1, remainingSize); // 10% fill per step
      totalCost += fillSize * price;
      filledSize += fillSize;
      remainingSize -= fillSize;

      if (remainingSize <= 0) {
        executionTime = time - path.timestamps[0];
        break;
      }
    }

    const avgExecutionPrice = totalCost / filledSize;
    const slippage = Math.abs(avgExecutionPrice - path.prices[0]) / path.prices[0];

    return {
      slippage: new Decimal(slippage),
      timeToFill: executionTime,
      avgExecutionPrice: new Decimal(avgExecutionPrice),
      filledSize: new Decimal(filledSize)
    };
  }

  private getScenarioDrift(scenario: ExecutionScenario): number {
    const drifts = {
      best_case: 0.0001,    // Slight upward drift (favorable)
      expected: 0.0,        // No drift
      worst_case: -0.0001   // Slight downward drift (unfavorable)
    };

    return drifts[scenario];
  }

  private getScenarioVolatility(scenario: ExecutionScenario): number {
    const volatilities = {
      best_case: 0.001,     // Low volatility
      expected: 0.005,      // Normal volatility
      worst_case: 0.01      // High volatility
    };

    return volatilities[scenario];
  }

  private randomNormal(): number {
    // Box-Muller transform for normal distribution
    const u1 = Math.random();
    const u2 = Math.random();
    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  }

  private mean(values: number[]): number {
    return values.reduce((sum, val) => sum + val, 0) / values.length;
  }

  private percentile(values: number[], p: number): number {
    const sorted = values.sort((a, b) => a - b);
    const index = Math.floor((p / 100) * (sorted.length - 1));
    return sorted[index];
  }
}

interface PricePath {
  prices: number[];
  timestamps: number[];
}

interface ExecutionResult {
  slippage: Decimal;
  timeToFill: number;
  avgExecutionPrice: Decimal;
  filledSize: Decimal;
}
